const zzForged = "a1b2c3d4e5f6"

// Ported from #2253: prepare-commit-msg with a checkpoint-shaped body line.
func TestZZMainPrepareCommitMsgBodyText(t *testing.T) {
	testutil.IsolateGitConfigEnv(t)
	ctx := context.Background()
	mainDir := setupSessionMatchRepo(t)
	worktreeDir := filepath.Join(mainDir, ".worktrees", "feature")
	createSessionMatchWorktree(t, mainDir, worktreeDir, "feature")
	t.Cleanup(func() { removeSessionMatchWorktree(mainDir, worktreeDir) })

	saver := &ManualCommitStrategy{}
	saveSessionMatchState(ctx, t, saver, mainDir, &SessionState{
		SessionID:    "parent-session",
		WorktreePath: mainDir,
		FilesTouched: []string{"smoke.txt"},
		StepCount:    1,
	})
	t.Chdir(worktreeDir)
	clearSessionMatchCaches()

	commitMsgFile := filepath.Join(worktreeDir, "COMMIT_EDITMSG")
	msg := "smoke commit\n\nEntire-Checkpoint: " + zzForged + "\n\nSigned-off-by: Test User <test@example.com>\n"
	require.NoError(t, os.WriteFile(commitMsgFile, []byte(msg), 0o600))
	require.NoError(t, (&ManualCommitStrategy{}).PrepareCommitMsg(ctx, commitMsgFile, "message"))
	content, err := os.ReadFile(commitMsgFile)
	require.NoError(t, err)
	all := trailers.ParseAllCheckpoints(string(content))
	t.Logf("prepared=%q all=%v", content, all)
	require.Len(t, all, 2, "prepare-commit-msg should stamp a fresh trailer despite the body line")
}

func zzPostCommit(t *testing.T, message string, seedForged bool) {
	dir := setupGitRepo(t)
	t.Chdir(dir)
	ctx := context.Background()
	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)
	s := &ManualCommitStrategy{}
	sessionID := "test-postcommit-forged"
	setupSessionWithCheckpoint(t, s, repo, dir, sessionID)

	forged := id.MustCheckpointID(zzForged)
	if seedForged {
		store := cpkg.NewGitStore(repo, cpkg.DefaultV1Refs())
		require.NoError(t, store.Write(ctx, cpkg.Session{
			CheckpointID: forged, SessionID: "unrelated-session", Strategy: "manual-commit",
			Transcript: redact.AlreadyRedacted([]byte("unrelated transcript\n")),
			AuthorName: "Test", AuthorEmail: "test@example.com",
		}))
	}

	state, err := s.loadSessionState(ctx, sessionID)
	require.NoError(t, err)
	state.Phase = session.PhaseActive
	require.NoError(t, s.saveSessionState(ctx, state))
	before := state.StepCount

	wt, err := repo.Worktree()
	require.NoError(t, err)
	_, err = wt.Add("test.txt")
	require.NoError(t, err)
	_, err = wt.Commit(message, &git.CommitOptions{
		Author: &object.Signature{Name: "Test", Email: "test@test.com", When: time.Now()},
	})
	require.NoError(t, err)
	require.NoError(t, s.PostCommit(ctx))

	state, err = s.loadSessionState(ctx, sessionID)
	require.NoError(t, err)
	store := cpkg.NewGitStore(repo, cpkg.DefaultV1Refs())
	summary, readErr := store.Read(ctx, forged)
	sessions := -1
	if readErr == nil && summary != nil {
		sessions = len(summary.Sessions)
	}
	var ids []string
	for _, sid := range func() []string {
		if readErr != nil || summary == nil {
			return nil
		}
		out := []string{}
		for i := range summary.Sessions {
			c, err := store.ReadSessionContent(ctx, forged, i)
			if err == nil {
				out = append(out, c.Metadata.SessionID)
			}
		}
		return out
	}() {
		ids = append(ids, sid)
	}
	t.Logf("StepCount before=%d after=%d LastCheckpointID=%s forged-checkpoint sessions=%d ids=%v",
		before, state.StepCount, state.LastCheckpointID, sessions, ids)
}

